begin;select plan(12);select has_table('public','apostolic_province_slot_layout');select has_table('public','apostolic_province_capital_state');select has_table('public','apostolic_province_capital_contributions');select is((select count(*)::integer from public.apostolic_province_slot_layout),16,'sixteen map slots');select is((select count(*)::integer from public.apostolic_province_slot_layout where x_percent not between 5 and 95 or y_percent not between 8 and 92),0,'slots inside map');select is((select count(*)::integer from pg_constraint where conrelid='public.apostolic_province_capital_contributions'::regclass and pg_get_constraintdef(oid)ilike'%gems%'),0,'no gems');select function_returns('public','apostolic_get_province_map',array[]::text[],'jsonb');select function_returns('public','apostolic_establish_province_capital',array[]::text[],'jsonb');select function_returns('public','apostolic_contribute_province_capital',array['text','integer','uuid'],'jsonb');select col_is_pk('public','apostolic_province_slot_layout','slot_no');select col_is_pk('public','apostolic_province_capital_state','province_id');select has_index('public','apostolic_province_capital_contributions','apostolic_capital_contributions_idx');select*from finish();rollback;
